'use client'

import { Heart, Share } from 'lucide-react'
import type { ReactNode } from 'react'
import type { Listing } from '../../types'

interface ListingHeaderProps {
  listing: Listing
}

/**
 * ListingHeader — the title row above the photo grid.
 * Shows the listing title, location, and Share/Save actions.
 */
export function ListingHeader({ listing }: ListingHeaderProps): ReactNode {
  return (
    <div className="title-row">
      <div>
        <h1>{listing.title}</h1>
        <p>{listing.location}</p>
      </div>
      <div className="title-actions">
        <button aria-label="Share this listing">
          <Share size={17} aria-hidden="true" />
          Share
        </button>
        <button aria-label="Save to wishlist">
          <Heart size={17} aria-hidden="true" />
          Save
        </button>
      </div>
    </div>
  )
}
