'use client'

import { CircleUserRound, Globe, Menu } from 'lucide-react'
import type { ReactNode } from 'react'
import { SearchPill } from './SearchPill'
import { CompactBar } from './CompactBar'

interface NavbarProps {
  compact: boolean
  price: string
  rating: string
  onScrollToPhotos: () => void
}

/**
 * Navbar — the fixed top navigation bar.
 * Renders the full nav (logo + search + actions) in default mode.
 * Renders the section tabs + reserve CTA in compact (scrolled) mode.
 */
export function Navbar({ compact, price, rating, onScrollToPhotos }: NavbarProps): ReactNode {
  return (
    <header className={`topbar${compact ? ' compact' : ''}`} role="banner">
      <div className="nav-inner">
        <button
          className="brand"
          onClick={onScrollToPhotos}
          aria-label="Airbnb — scroll to top"
        >
          <span className="brand-mark" aria-hidden="true">⌂</span>
          <span>airbnb</span>
        </button>

        {compact ? (
          <CompactBar
            price={price}
            rating={rating}
            onPhotos={onScrollToPhotos}
          />
        ) : (
          <>
            <SearchPill />
            <div className="nav-actions">
              <button>Become a host</button>
              <button aria-label="Select language">
                <Globe size={18} aria-hidden="true" />
              </button>
              <button
                className="menu-btn"
                aria-label="Open menu"
                aria-haspopup="true"
              >
                <Menu size={19} aria-hidden="true" />
                <CircleUserRound size={19} aria-hidden="true" />
              </button>
            </div>
          </>
        )}
      </div>
    </header>
  )
}
