'use client'

import Image from 'next/image'
import type { ReactNode } from 'react'
import type { Photo } from '../../types'
import { PhotoThumbnail } from './PhotoThumbnail'

interface PhotoGridProps {
  photos: Photo[]
  onPhotoClick: (index: number) => void
}

/**
 * PhotoGrid — the 5-photo hero grid matching reference screenshot.
 * Hero photo on left (50%), 4 small photos in 2x2 grid on right (50%),
 * with floating "Show all photos" button in bottom right.
 */
export function PhotoGrid({ photos, onPhotoClick }: PhotoGridProps): ReactNode {
  const [hero, ...smallPhotos] = photos.slice(0, 5)

  return (
    <section className="photo-grid" id="photos" aria-label="Property photos">
      <div className="photo-grid-wrapper">
        {/* Hero photo (left 50%) */}
        <button
          type="button"
          className="hero-photo photo-button"
          onClick={() => onPhotoClick(0)}
          aria-label={`View photo: ${hero.alt}`}
        >
          <Image
            src={hero.src}
            alt={hero.alt}
            fill
            priority
            sizes="(max-width: 768px) 100vw, 50vw"
          />
        </button>

        {/* 4 smaller photos in 2x2 grid (right 50%) */}
        <div className="small-photos">
          {smallPhotos.slice(0, 4).map((photo, i) => (
            <PhotoThumbnail
              key={photo.src}
              photo={photo}
              index={i + 1}
              onClick={onPhotoClick}
            />
          ))}
        </div>

        {/* Floating "Show all photos" button matching reference screenshot */}
        <button
          type="button"
          className="show-all-photos-btn"
          onClick={() => onPhotoClick(0)}
          aria-label="Show all photos"
        >
          <svg viewBox="0 0 16 16" width="16" height="16" fill="currentColor" aria-hidden="true">
            <circle cx="2" cy="2" r="1.5" />
            <circle cx="8" cy="2" r="1.5" />
            <circle cx="14" cy="2" r="1.5" />
            <circle cx="2" cy="8" r="1.5" />
            <circle cx="8" cy="8" r="1.5" />
            <circle cx="14" cy="8" r="1.5" />
            <circle cx="2" cy="14" r="1.5" />
            <circle cx="8" cy="14" r="1.5" />
            <circle cx="14" cy="14" r="1.5" />
          </svg>
          <span>Show all photos</span>
        </button>
      </div>
    </section>
  )
}
