import type { ReactNode } from 'react'
import { getRatingBarWidth } from '../../utils/formatting'
import { RATING_CATEGORIES } from '../../constants/mock-data'

/**
 * RatingBars — the overall rating bar chart and per-category scores.
 * Bar widths are computed from getRatingBarWidth() — not inline magic strings.
 */
export function RatingBars(): ReactNode {
  const starCounts = [5, 4, 3, 2, 1]

  return (
    <div className="rating-cats" aria-label="Rating breakdown">
      {/* Overall bar chart */}
      <div className="bars">
        <b>
          Overall rating <span>4.95</span>
        </b>
        {starCounts.map((n) => (
          <div key={n}>
            <small>{n}</small>
            <i aria-hidden="true">
              <em style={{ width: getRatingBarWidth(n) }} />
            </i>
          </div>
        ))}
      </div>

      {/* Category scores */}
      {RATING_CATEGORIES.map(({ name, score }) => (
        <div className="cat" key={name}>
          <span>{name}</span>
          <b>{score}</b>
        </div>
      ))}
    </div>
  )
}
